import Foundation

@MainActor
final class CheckoutViewModel: ObservableObject {
    enum State {
        case idle, submitting, retrying(Int), submitted, failed
    }

    @Published private(set) var state: State = .idle
    private let api: OrdersAPI
    private let order: OrderDraft

    init(api: OrdersAPI, order: OrderDraft) {
        self.api = api
        self.order = order
    }

    func submit() async {
        state = .submitting
        for attempt in 1...3 {
            do {
                try await api.submit(order)
                state = .submitted
                return
            } catch {
                state = .retrying(attempt)
                Thread.sleep(forTimeInterval: 1.0)
            }
        }
        state = .failed
    }
}

